vec4 shade(vec2 uv) {
  vec4 c = source(uv);
  float light = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
  float hot = smoothstep(p_threshold, min(1.0, p_threshold + 0.23), light);
  return vec4(mix(c.rgb, vec3(1.0, 0.52, 0.22), 0.38), hot * c.a);
}

vec4 shade(vec2 uv) {
  vec2 stepUV = vec2(uTexel.x, 0.0) * (p_radius / 4.0);
  vec4 sum = vec4(0.0);
  float weights = 0.0;
  for (int i = 0; i < 9; i++) {
    float offset = float(i) - 4.0;
    float weight = exp(-offset * offset * 0.18);
    vec4 c = inputColor(uv + stepUV * offset);
    sum += vec4(c.rgb * c.a, c.a) * weight;
    weights += weight;
  }
  return vec4(sum.rgb / max(0.00001, sum.a), sum.a / weights);
}

vec4 shade(vec2 uv) {
  vec2 stepUV = vec2(0.0, uTexel.y) * (p_radius / 4.0);
  vec4 sum = vec4(0.0);
  float weights = 0.0;
  for (int i = 0; i < 9; i++) {
    float offset = float(i) - 4.0;
    float weight = exp(-offset * offset * 0.18);
    vec4 c = inputColor(uv + stepUV * offset);
    sum += vec4(c.rgb * c.a, c.a) * weight;
    weights += weight;
  }
  return vec4(sum.rgb / max(0.00001, sum.a), sum.a / weights);
}

vec4 shade(vec2 uv) {
  vec4 c = source(uv);
  vec4 g = sample_spreadY(uv);
  float halo = clamp(g.a * p_intensity * 0.65, 0.0, 1.0);
  float a = c.a + halo * (1.0 - c.a);
  vec3 lit = 1.0 - (1.0 - c.rgb) * (1.0 - g.rgb * halo);
  vec3 premult = lit * c.a + g.rgb * halo * (1.0 - c.a);
  return vec4(premult / max(0.00001, a), a);
}
